import XCTest
@testable import BetaTokensCore

/// Fabricated credentials only - never real Apple data.
final class CoreTests: XCTestCase {
    let fake = Credentials(consumerKey: "CK_FAKE", consumerSecret: "CS_FAKE",
                           accessToken: "AT_FAKE", accessSecret: "AS_FAKE")

    func tempDir() -> URL {
        URL(fileURLWithPath: ProcessInfo.processInfo.environment["OBT_TMP"] ?? NSTemporaryDirectory()).appendingPathComponent("obt-\(UUID().uuidString)")
    }

    // The expected header was generated by the Python implementation (tools/ and src/oauth.py)
    // with the same inputs, so this proves the Swift port signs identically.
    func testOAuthMatchesPythonReference() {
        let h = OAuth1.header(method: "GET", url: ABMClient.sessionURL, credentials: fake,
                              timestamp: 1_700_000_000, nonce: "abcd1234abcd1234")
        let expected = "OAuth realm=\"ADM\",oauth_consumer_key=\"CK_FAKE\",oauth_nonce=\"abcd1234abcd1234\"," +
            "oauth_signature_method=\"HMAC-SHA1\",oauth_timestamp=\"1700000000\",oauth_token=\"AT_FAKE\"," +
            "oauth_version=\"1.0\",oauth_signature=\"RtK5Tl8tInvxynxWC5uWpDJzDj8%3D\""
        XCTAssertEqual(h, expected)
    }

    func testUrlEncode() { XCTAssertEqual(OAuth1.urlEncode("a b/c~"), "a%20b%2Fc~") }

    func testSecretsNeverInDescription() {
        XCTAssertFalse("\(fake)".contains("CS_FAKE"))
        XCTAssertFalse("\(fake)".contains("AS_FAKE"))
        XCTAssertFalse("\(BetaToken(title: "t", os: "iOS", token: String(repeating: "T", count: 40)))".contains("TTTT"))
    }

    func testKeypairPermissionsAndNoOverwrite() throws {
        let dir = tempDir()
        let (key, _) = try ServerToken.generateKeypair(in: dir)
        let mode = try FileManager.default.attributesOfItem(atPath: key.path)[.posixPermissions] as? Int
        XCTAssertEqual(mode, 0o600)
        XCTAssertThrowsError(try ServerToken.generateKeypair(in: dir))
    }

    func makeP7M(dir: URL, payload: String) throws -> URL {
        let out = dir.appendingPathComponent("fake.p7m")
        let r = try ServerToken.runOpenSSL(
            ["smime", "-encrypt", "-aes256", "-out", out.path, dir.appendingPathComponent(ServerToken.certName).path],
            input: Data(payload.utf8))
        XCTAssertEqual(r.status, 0, String(decoding: r.err, as: UTF8.self))
        return out
    }

    func testDecryptRoundTrip() throws {
        let dir = tempDir()
        try ServerToken.generateKeypair(in: dir)
        let json = #"{"consumer_key":"CK_FAKE","consumer_secret":"CS_FAKE","access_token":"AT_FAKE","access_secret":"AS_FAKE","access_token_expiry":"2099-01-01T00:00:00Z"}"#
        let p7m = try makeP7M(dir: dir, payload: "-----BEGIN MESSAGE-----\n\(json)\n-----END MESSAGE-----\n")
        let creds = try ServerToken.decrypt(p7m: p7m, workdir: dir)
        XCTAssertEqual(creds.consumerKey, "CK_FAKE")
        XCTAssertEqual(creds.accessTokenExpiry, "2099-01-01T00:00:00Z")
    }

    func testWrongCertFails() throws {
        let a = tempDir(), b = tempDir()
        try ServerToken.generateKeypair(in: a)
        try ServerToken.generateKeypair(in: b)
        let p7m = try makeP7M(dir: a, payload: "{}")
        XCTAssertThrowsError(try ServerToken.decrypt(p7m: p7m, workdir: b))
    }

    func testFetchWithFakeTransport() async throws {
        let tokensBody = #"{"betaEnrollmentTokens":[{"title":"macOS Test Beta","os":"OSX","token":"TTTTTTTTTTTTTTTTTTTT"},{"title":"iOS Test Beta","os":"iOS","token":"UUUUUUUUUUUUUUUUUUUU"}]}"#
        let client = ABMClient { req in
            let url = req.url!.absoluteString
            if url == ABMClient.sessionURL {
                XCTAssertTrue(req.value(forHTTPHeaderField: "Authorization")!.hasPrefix("OAuth realm=\"ADM\""))
                return (Data(#"{"auth_session_token":"S"}"#.utf8), 200)
            }
            XCTAssertEqual(req.value(forHTTPHeaderField: "X-ADM-Auth-Session"), "S")
            XCTAssertEqual(req.value(forHTTPHeaderField: "X-Server-Protocol-Version"), "1")
            return (Data(tokensBody.utf8), 200)
        }
        let tokens = try await client.fetchBetaTokens(fake)
        XCTAssertEqual(Set(tokens.map(\.osDisplay)), ["macOS", "iOS"])
    }

    func testSeedTurnedOffMessage() async {
        let client = ABMClient { _ in (Data(#"{"reason":"APPLE_SEED_FOR_IT_TURNED_OFF"}"#.utf8), 403) }
        do { _ = try await client.betaTokens(session: "S"); XCTFail("expected error") }
        catch { XCTAssertTrue(error.localizedDescription.contains("beta.apple.com/for-it")) }
    }

    func testSessionFailure() async {
        let client = ABMClient { _ in (Data(), 401) }
        do { _ = try await client.sessionToken(fake); XCTFail("expected error") }
        catch { XCTAssertTrue(error.localizedDescription.contains("401")) }
    }

    func testRenderFilterAndDeclaration() throws {
        let toks = [BetaToken(title: "macOS Test Beta", os: "OSX", token: String(repeating: "M", count: 40)),
                    BetaToken(title: "iOS Test Beta", os: "iOS", token: String(repeating: "I", count: 40))]
        XCTAssertEqual(Render.filter(toks, os: "macOS").count, 1)
        XCTAssertEqual(Render.filter(toks, text: "ios").count, 1)
        let d = try JSONSerialization.jsonObject(with: Data(Render.declaration(for: toks[0]).utf8)) as! [String: Any]
        let beta = (d["Payload"] as! [String: Any])["Beta"] as! [String: Any]
        XCTAssertEqual(beta["ProgramEnrollment"] as? String, "Allowed")
        XCTAssertNotNil(beta["RequireProgram"])
        let d2 = try JSONSerialization.jsonObject(
            with: Data(Render.declaration(for: toks[0], enrollment: .alwaysOn, requireProgram: false).utf8)) as! [String: Any]
        XCTAssertNotNil(((d2["Payload"] as! [String: Any])["Beta"] as! [String: Any])["OfferPrograms"])
    }
}
